import {
    CURRENT_RELEASE_IDENTITY,
    type LoadedStatsSource,
    type StatsControls,
    type StatsDatasetSource,
    type StatsOptions,
    type StatsReleaseOption,
    type StatsReleaseSelection,
} from './project_stats_types';
import { accountSeriesIdentity, modelIdentity } from './stats_identities';

function optionList(entries: Array<[string, string]>) {
    return [...new Map(entries).entries()]
        .map(([identity, label]) => ({ identity, label }))
        .sort((left, right) => left.label.localeCompare(right.label) || left.identity.localeCompare(right.identity));
}

export function completedReleaseIdentity(releaseName: string) {
    return `completed-release:${releaseName}`;
}

/** Builds stable release choices without treating persistence paths as release identity. */
export function buildReleaseOptions(source: LoadedStatsSource): StatsReleaseOption[] {
    const completedReleases = Object.keys(source.releaseStats)
        .sort((left, right) => left.localeCompare(right))
        .map((releaseName) => ({ identity: completedReleaseIdentity(releaseName), label: releaseName, releaseName }));

    return [{ identity: CURRENT_RELEASE_IDENTITY, label: 'Current release', releaseName: null }, ...completedReleases];
}

/** Derives entity and account-series catalogs from selected releases plus release choices. */
export function buildOptions(source: StatsDatasetSource, releases: StatsReleaseOption[]): StatsOptions {
    const attributed = source.stats.conversations.filter(({ agent, isRootConversation, model }) => isRootConversation && agent && model);
    const actions = optionList([
        ...source.stats.actions.map(({ actionId, actionLabel }) => [actionId, actionLabel] as [string, string]),
        ...source.stats.conversations.flatMap(({ actionId, actionLabel }) => (
            actionId ? [[actionId, actionLabel ?? actionId] as [string, string]] : []
        )),
    ]);
    const agents = optionList(attributed.map(({ agent }) => [agent!, agent!]));
    const models = optionList(attributed.map(({ agent, model }) => [modelIdentity(agent!, model!), `${agent} - ${model}`]));
    const accountSeries = [...new Map(source.accountRows.map((row) => [accountSeriesIdentity(row), {
        identity: accountSeriesIdentity(row),
        limitId: row.limitId,
        provider: row.provider,
        windowDurationMinutes: row.windowDurationMinutes,
        windowId: row.windowId,
    }])).values()].sort((left, right) => left.identity.localeCompare(right.identity));

    return { accountSeries, actions, agents, models, releases };
}

function retainValidSelections(selected: string[], available: Set<string>) {
    return selected.filter((identity) => available.has(identity));
}

export function reconcileReleaseSelection(selection: StatsReleaseSelection, releases: StatsReleaseOption[]): StatsReleaseSelection {
    if (selection.mode === 'all') return selection;
    const identities = retainValidSelections(selection.identities, new Set(releases.map(({ identity }) => identity)));
    return {
        mode: 'selected',
        identities: selection.identities.length > 0 && identities.length === 0 ? [CURRENT_RELEASE_IDENTITY] : identities,
    };
}

/** Drops entity selections that the freshly loaded source no longer offers. */
export function reconcileControls(controls: StatsControls, options: StatsOptions): StatsControls {
    return {
        ...controls,
        performanceActionIds: retainValidSelections(
            controls.performanceActionIds,
            new Set(options.actions.map(({ identity }) => identity)),
        ),
        performanceAgentIds: retainValidSelections(controls.performanceAgentIds, new Set(options.agents.map(({ identity }) => identity))),
        performanceModelIds: retainValidSelections(controls.performanceModelIds, new Set(options.models.map(({ identity }) => identity))),
        releaseSelection: reconcileReleaseSelection(controls.releaseSelection, options.releases),
    };
}

import { projectUsageMetricsService } from '../agents/project_usage_metrics_service';
import { configService } from '../config/config_service';
import type { AgentProfile } from '../../data/agent_profiles';
import { register } from '../service_injector';
import { ProjectStatsLoader, type StatsCalculator } from './project_stats_loader';
import {
    INITIAL_CONTROLS,
    INITIAL_SNAPSHOT,
    type LoadedStatsSource,
    type ProjectStatsSnapshot,
    type StatsCardDescriptor,
    type StatsControls,
    type StatsProjectBinding,
    type StatsViewMode,
} from './project_stats_types';
import { buildSnapshot } from './stats_snapshot_builder';
import { registerSeriesLabels, type StatsSeriesSlots } from './stats_series_slots';

function isValidIsoTimestamp(value: string) {
    const milliseconds = Date.parse(value);

    return Number.isFinite(milliseconds) && new Date(milliseconds).toISOString() === value;
}

function validateRangeTimestamp(value: string | null, field: string) {
    if (value !== null && !isValidIsoTimestamp(value)) throw new Error(`Invalid stats ${field}`);
}

/** Owns the stats viewing session: binding, load coordination, control updates, and snapshot notifications. */
export class ProjectStatsService extends EventTarget {
    private abortController: AbortController | null = null;
    private readonly loader: ProjectStatsLoader;
    private loadRevision = 0;
    private binding: StatsProjectBinding | null = null;
    private cards: StatsCardDescriptor[] = [];
    private isOpen = false;
    private projectKey: string | null = null;
    private snapshot = INITIAL_SNAPSHOT;
    // Remembered for the whole app session so a label keeps its color across filters, reopening, and projects.
    private seriesColorSlots: StatsSeriesSlots = new Map();
    private source: LoadedStatsSource | null = null;
    private viewModeChoice: StatsViewMode | null = null;

    constructor(calculateStats?: StatsCalculator) {
        super();
        this.loader = new ProjectStatsLoader(calculateStats);
    }

    getSnapshot = () => this.snapshot;

    subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener);

        return () => this.removeEventListener('changed', listener);
    };

    getSeriesColorSlots = () => this.seriesColorSlots;

    subscribeSeriesColors = (listener: () => void) => {
        this.addEventListener('seriesColorsChanged', listener);

        return () => this.removeEventListener('seriesColorsChanged', listener);
    };

    getViewModeChoice = () => this.viewModeChoice;

    subscribeViewMode = (listener: () => void) => {
        this.addEventListener('viewModeChanged', listener);

        return () => this.removeEventListener('viewModeChanged', listener);
    };

    setViewModeChoice(mode: StatsViewMode) {
        if (this.viewModeChoice === mode) return;
        this.viewModeChoice = mode;
        this.dispatchEvent(new Event('viewModeChanged'));
    }

    bindProject(binding: StatsProjectBinding) {
        const projectKey = `${binding.project.id}:${binding.project.branch}`;
        if (projectKey !== this.projectKey) this.clear();
        this.projectKey = projectKey;
        this.binding = binding;
    }

    clear() {
        this.close();
        this.binding = null;
        this.projectKey = null;
        this.publish({
            ...this.snapshot,
            controls: {
                ...this.snapshot.controls,
                granularity: INITIAL_CONTROLS.granularity,
                releaseSelection: INITIAL_CONTROLS.releaseSelection,
            },
        });
        if (this.viewModeChoice !== null) {
            this.viewModeChoice = null;
            this.dispatchEvent(new Event('viewModeChanged'));
        }
    }

    async open(cards: StatsCardDescriptor[], agentProfiles: AgentProfile[] = configService.get('desktop.agentProfiles')) {
        if (!this.binding) throw new Error('Project stats are not bound to a project');
        if (this.isOpen) return;
        this.cards = cards;
        this.isOpen = true;
        this.abortController = new AbortController();
        await this.load(this.binding, agentProfiles, this.abortController.signal);
    }

    close() {
        this.loadRevision += 1;
        this.abortController?.abort();
        this.abortController = null;
        this.cards = [];
        this.isOpen = false;
        this.source = null;
        projectUsageMetricsService.clear();
        this.publish({ ...INITIAL_SNAPSHOT, controls: this.snapshot.controls });
    }

    setControls(changes: Partial<StatsControls>) {
        const controls = { ...this.snapshot.controls, ...changes };
        validateRangeTimestamp(controls.startUtc, 'startUtc');
        validateRangeTimestamp(controls.endUtc, 'endUtc');
        if (controls.startUtc && controls.endUtc && Date.parse(controls.startUtc) > Date.parse(controls.endUtc)) {
            throw new Error('Stats start date must not be after end date');
        }
        // A display-only control changes no aggregated row, so keep the existing rows object
        // instead of paying for a full rebuild.
        const changedKeys = Object.keys(changes) as (keyof StatsControls)[];
        const displayOnly = changedKeys.length > 0
            && changedKeys.every((key) => key === 'shortTokenCounts');
        if (!this.source || displayOnly) {
            this.publish({ ...this.snapshot, controls });
            return;
        }

        this.publish(buildSnapshot(this.source, controls));
    }

    private async load(binding: StatsProjectBinding, agentProfiles: AgentProfile[], signal: AbortSignal) {
        const revision = ++this.loadRevision;
        const isCurrent = () => this.isCurrentLoad(revision, binding, signal);
        this.publish({ ...this.snapshot, error: null, rows: [], status: 'loading' });
        try {
            const source = await this.loader.loadSource(binding, this.cards, signal, isCurrent);
            if (!source) return;
            this.source = { ...source, agentProfiles };
            this.publish(buildSnapshot(this.source, this.snapshot.controls));
        } catch (error) {
            if (!isCurrent()) return;
            const normalizedError = error instanceof Error ? error : new Error(String(error));
            this.source = null;
            this.publish({ ...this.snapshot, error: normalizedError, rows: [], status: 'error' });
        }
    }

    private isCurrentLoad(revision: number, binding: StatsProjectBinding, signal: AbortSignal) {
        return !signal.aborted && this.isOpen && revision === this.loadRevision && binding === this.binding;
    }

    private publish(snapshot: ProjectStatsSnapshot) {
        this.snapshot = snapshot;
        const seriesColorSlots = registerSeriesLabels(this.seriesColorSlots, snapshot.rows);
        if (seriesColorSlots !== this.seriesColorSlots) {
            this.seriesColorSlots = seriesColorSlots;
            this.dispatchEvent(new Event('seriesColorsChanged'));
        }
        this.dispatchEvent(new Event('changed'));
    }
}

export const projectStatsService = register('projectStatsService', new ProjectStatsService());

import type { UsageMetricsAccountRow } from '../agents/project_usage_metrics_service';
