        agentIdentities.add(agent ?? UNKNOWN_AGENT_LABEL);
        const rate = agent === null ? undefined : rates.get(agent);
        if (rate?.available) {
            value += totalTokens / rate.tokensPerDollar;
            pricedRunCount += 1;
            continue;
