export type ActionScheduleSnapshot =
    | AccountResetActionScheduleSnapshot
    | AtActionScheduleSnapshot
    | CardStateActionScheduleSnapshot

export type ActionScheduleStoreSnapshot = ActionScheduleSnapshot & { anchorElement: HTMLElement | null }

interface AccountResetDraft {
    agent: string
    limitId: string
    windowId: string
}

interface CardStateDraft {
    cardInternalId: string
    targetState: string
}

const INITIAL_SNAPSHOT: ActionScheduleStoreSnapshot = {
    anchorElement: null,
    message: null,
    open: false,
    timestamp: '',
    triggerType: 'at',
}

/** Owns trigger-specific schedule form state at schedule-section boundary. */
export class ActionScheduleStore extends EventTarget {
    private readonly accountResetDraft: AccountResetDraft = { agent: '', limitId: '', windowId: '' }
    private readonly cardStateDraft: CardStateDraft = { cardInternalId: '', targetState: '' }
    private snapshot: ActionScheduleStoreSnapshot = INITIAL_SNAPSHOT
    private timestamp = ''

    readonly getSnapshot = () => this.snapshot
    readonly getOpenSnapshot = () => this.snapshot.open

    readonly subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    toggle(anchorElement: HTMLElement) {
        if (this.snapshot.open) {
            this.close()
            return
        }

        this.publish({ ...this.snapshot, anchorElement, message: null, open: true })
    }

    close() {
        const { anchorElement, message, open } = this.snapshot
        if (!open && anchorElement === null && message === null) return

        this.publish({ ...this.snapshot, anchorElement: null, message: null, open: false })
    }

    setTriggerType(triggerType: ActionScheduleTriggerType) {
        if (triggerType === this.snapshot.triggerType) return

        const common = { anchorElement: this.snapshot.anchorElement, message: null, open: this.snapshot.open }
        if (triggerType === 'at') {
            this.publish({ ...common, timestamp: this.timestamp, triggerType })
            return
        }
        if (triggerType === 'account-reset') {
            this.publish({ ...common, ...this.accountResetDraft, triggerType })
            return
        }

        this.publish({ ...common, ...this.cardStateDraft, triggerType })
    }

    setTimestamp(timestamp: string) {
        this.timestamp = timestamp
        if (this.snapshot.triggerType === 'at') this.publish({ ...this.snapshot, message: null, timestamp })
    }

    setAgent(agent: string) {
        this.accountResetDraft.agent = agent
        this.accountResetDraft.limitId = ''
        this.accountResetDraft.windowId = ''
        if (this.snapshot.triggerType === 'account-reset') {
            this.publish({ ...this.snapshot, ...this.accountResetDraft, message: null })
        }
    }

    setAccountTracker(limitId: string, windowId: string) {
        this.accountResetDraft.limitId = limitId
        this.accountResetDraft.windowId = windowId
        if (this.snapshot.triggerType === 'account-reset') {
            this.publish({ ...this.snapshot, ...this.accountResetDraft, message: null })
        }
    }

    setCardInternalId(cardInternalId: string) {
        this.cardStateDraft.cardInternalId = cardInternalId
        if (this.snapshot.triggerType === 'card-state') {
            this.publish({ ...this.snapshot, cardInternalId, message: null })
        }
    }

    setTargetState(targetState: string) {
        this.cardStateDraft.targetState = targetState
        if (this.snapshot.triggerType === 'card-state') {
            this.publish({ ...this.snapshot, message: null, targetState })
        }
    }

    setMessage(message: string | null) {
        this.publish({ ...this.snapshot, message })
    }

    private publish(snapshot: ActionScheduleStoreSnapshot) {
        this.snapshot = snapshot
        this.dispatchEvent(new Event('changed'))
    }
}

import type { ActionScheduleTrigger } from '../../../../data/action_schedule_types'
import type { ActionScheduleAccountTracker, ActionScheduleCardOption } from './action_schedule_options'
import type { ActionScheduleSnapshot } from './action_schedule_store'

export interface ActionScheduleTriggerSources {
    accountTrackers: ActionScheduleAccountTracker[]
    cards: ActionScheduleCardOption[]
    targetStates: string[]
}

function createAtScheduleTrigger(timestampInput: string, now: number): ActionScheduleTrigger {
    const timestamp = timestampInput.trim()
    if (timestamp.length === 0) throw new Error('Timestamp is required for time schedules')
    const fireAt = Date.parse(timestamp)
    if (Number.isNaN(fireAt)) throw new Error('Schedule timestamp is invalid')
    if (fireAt <= now) throw new Error('Schedule time must be in the future')

    return { timestamp: new Date(fireAt).toISOString(), type: 'at' }
}

function createAccountResetScheduleTrigger(
    snapshot: Extract<ActionScheduleSnapshot, { triggerType: 'account-reset' }>,
    accountTrackers: ActionScheduleAccountTracker[],
): ActionScheduleTrigger {
    if (!snapshot.agent) throw new Error('Agent is required for account reset schedules')
    const tracker = accountTrackers.find(({ agent, limitId, windowId }) => (
        agent === snapshot.agent && limitId === snapshot.limitId && windowId === snapshot.windowId
    ))
    if (!tracker) throw new Error('Selected account tracker is unavailable')
    if (!tracker.expectedResetAt) throw new Error('Selected account tracker has no reset time')

    return {
        agent: tracker.agent,
        expectedResetAt: tracker.expectedResetAt,
        limitId: tracker.limitId,
        type: 'account-reset',
        windowId: tracker.windowId,
    }
}

function createCardStateScheduleTrigger(
    snapshot: Extract<ActionScheduleSnapshot, { triggerType: 'card-state' }>,
    cards: ActionScheduleCardOption[],
    targetStates: string[],
): ActionScheduleTrigger {
    const card = cards.find(({ cardInternalId }) => cardInternalId === snapshot.cardInternalId)
    if (!card) throw new Error('Selected trigger card is unavailable')
    if (!card.registrationState) throw new Error('Selected trigger card has no current state')
    if (!targetStates.includes(snapshot.targetState)) throw new Error('Selected target state is unavailable')

    return {
        cardInternalId: card.cardInternalId,
        registrationState: card.registrationState,
        targetState: snapshot.targetState,
        type: 'card-state',
    }
}

/** Validate active schedule fields and build only selected trigger payload. */
export function createScheduleTrigger(
    snapshot: ActionScheduleSnapshot,
    sources: ActionScheduleTriggerSources,
    now = Date.now(),
): ActionScheduleTrigger {
    if (snapshot.triggerType === 'at') return createAtScheduleTrigger(snapshot.timestamp, now)
    if (snapshot.triggerType === 'account-reset') {
        return createAccountResetScheduleTrigger(snapshot, sources.accountTrackers)
    }

    return createCardStateScheduleTrigger(snapshot, sources.cards, sources.targetStates)
}

export function canRegisterSchedule(snapshot: ActionScheduleSnapshot, sources: ActionScheduleTriggerSources, now = Date.now()) {
    try {
        createScheduleTrigger(snapshot, sources, now)
        return true
    } catch {
        return false
    }
}

